"""幸运方块掉落池全局校验：可达性、缺失文件、未定义物品 id、空池、JSON 合法性。"""
import json
import os

MAP = r"C:\Users\UserX\Downloads\幸运方块地图_法杖增强版_竞技场版"
BP = os.path.join(MAP, "behavior_packs", "LuckyBlock")
LT = os.path.join(BP, "loot_tables")

errors = []
warnings = []


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


# ---------- 1. 收集所有合法物品 id ----------
defined = set()
for base in (os.path.join(BP, "items"), os.path.join(MAP, "behavior_packs", "BlockArmor BP V2.1.6", "items"),
             os.path.join(BP, "blocks")):
    for root, _dirs, files in os.walk(base):
        for fn in files:
            if fn.endswith(".json"):
                try:
                    d = load_json(os.path.join(root, fn))
                except Exception as e:
                    errors.append(f"BAD JSON {os.path.join(root, fn)}: {e}")
                    continue
                ident = (d.get("minecraft:item") or d.get("minecraft:block") or {}).get("description", {}).get("identifier")
                if ident:
                    defined.add(ident)

# ---------- 2. 计算可达闭包 ----------
def refs_in(path):
    d = load_json(path)
    out = []

    def walk(n):
        if isinstance(n, dict):
            if n.get("type") == "loot_table" and "name" in n:
                out.append(n["name"])
            for v in n.values():
                walk(v)
        elif isinstance(n, list):
            for v in n:
                walk(v)

    walk(d)
    return out


roots = []
src_js = os.path.join(BP, "scripts")
import re
for fn in os.listdir(src_js):
    if fn.endswith(".js"):
        with open(os.path.join(src_js, fn), "r", encoding="utf-8") as f:
            for m in re.finditer(r'loot\s+"([^"]+)"', f.read()):
                roots.append("loot_tables/" + m.group(1) + ".json")
for sub in ("blocks", "entities"):
    for root, _d, files in os.walk(os.path.join(BP, sub)):
        for fn in files:
            if fn.endswith(".json"):
                try:
                    d = load_json(os.path.join(root, fn))
                except Exception:
                    continue
                txt = json.dumps(d)
                for m in re.finditer(r'"(loot_tables/[^"]+\.json)"', txt):
                    roots.append(m.group(1))

live = set()
work = list(roots)
while work:
    cur = work.pop()
    if cur in live:
        continue
    live.add(cur)
    p = os.path.join(BP, cur)
    if not os.path.exists(p):
        continue
    for r in refs_in(p):
        if r not in live:
            work.append(r)

vanilla_prefixes = (
    "minecraft:", "chests/", "gameplay/", "loot_tables/chests/", "loot_tables/gameplay/",
)

missing = sorted(r for r in live if not os.path.exists(os.path.join(BP, r))
                 and not r.startswith(vanilla_prefixes))

# ---------- 3. 逐张检查可达表 ----------
checked = 0
for rel in sorted(live):
    p = os.path.join(BP, rel)
    if not os.path.exists(p):
        continue
    if rel.startswith(("loot_tables/chests/", "loot_tables/gameplay/")):
        continue
    try:
        d = load_json(p)
    except Exception as e:
        errors.append(f"BAD JSON {rel}: {e}")
        continue
    checked += 1
    pools = d.get("pools", [])
    if not pools:
        warnings.append(f"空战利品表（无 pools）: {rel}")
        continue
    for i, pool in enumerate(pools):
        ents = pool.get("entries", [])
        if not ents:
            warnings.append(f"空池: {rel} pool{i}")

        def walk(n):
            if isinstance(n, dict):
                if n.get("type") == "item" and "name" in n:
                    nm = n["name"]
                    if not nm.startswith("minecraft:") and nm not in defined:
                        errors.append(f"未定义物品 id: {rel} -> {nm}")
                for v in n.values():
                    walk(v)
            elif isinstance(n, list):
                for v in n:
                    walk(v)

        walk(pool)

print(f"定义物品 id: {len(defined)}，可达战利品表: {len(live)}，实际检查: {checked}")
print()
print("### 缺失文件（可达但不存在，排除原版内建表）")
for m in missing:
    print("  ", m)
if not missing:
    print("   （无）")
print()
print("### 错误")
for e in errors:
    print("  ", e)
if not errors:
    print("   （无）")
print()
print("### 警告")
for w in warnings:
    print("  ", w)
if not warnings:
    print("   （无）")
