import json
import os
import re

MAP = r"C:\Users\UserX\Downloads\幸运方块地图_法杖增强版_竞技场版"
BP = os.path.join(MAP, "behavior_packs", "LuckyBlock")


def refs(path):
    with open(path, "r", encoding="utf-8") as f:
        d = json.load(f)
    out = []

    def walk(n):
        if isinstance(n, dict):
            if n.get("type") == "loot_table" and "name" in n:
                out.append(n["name"])
            for v in n.values():
                walk(v)
        elif isinstance(n, list):
            for v in n:
                walk(v)

    walk(d)
    return out


roots = []
for fn in os.listdir(os.path.join(BP, "scripts")):
    if fn.endswith(".js"):
        with open(os.path.join(BP, "scripts", fn), "r", encoding="utf-8") as f:
            roots += ["loot_tables/" + m + ".json" for m in re.findall(r'loot\s+"([^"]+)"', f.read())]
for sub in ("blocks", "entities"):
    for root, _d, files in os.walk(os.path.join(BP, sub)):
        for fn in files:
            if fn.endswith(".json"):
                try:
                    with open(os.path.join(root, fn), "r", encoding="utf-8") as f:
                        txt = f.read()
                except Exception:
                    continue
                roots += re.findall(r'"(loot_tables/[^"]+\.json)"', txt)

live, work = set(), list(roots)
while work:
    cur = work.pop()
    if cur in live:
        continue
    live.add(cur)
    p = os.path.join(BP, cur)
    if os.path.exists(p):
        work += [r for r in refs(p) if r not in live]

