    if not os.path.exists(p):
        continue
    try:
        d = json.load(p and open(p, "r", encoding="utf-8"))
    except Exception:
        continue

    def walk(n):
        if isinstance(n, dict):
            if n.get("type") == "item" and "name" in n:
                items.append((rel, n["name"]))
            for v in n.values():
                walk(v)
        elif isinstance(n, list):
            for v in n:
                walk(v)

    walk(d)

print("### 应当已被移除（可达池内剩余命中）")
