```js
/**
 * 极低概率灾难：雷暴 + 凋零。
 * 持续 10 秒不停劈雷，同时召唤一只凋零，90 秒后自动清除。
 */
import { system, world, TicksPerSecond } from "@minecraft/server"

/** 雷暴持续 10 秒。 */
const STORM_TICKS = 10 * TicksPerSecond
/** 每波雷击的间隔。 */
const STORM_WAVE_INTERVAL = 10
/** 每波劈下的闪电数量范围。 */
const BOLTS_MIN = 4
const BOLTS_MAX = 8
/** 闪电散布半径。 */
const BOLT_RADIUS = 7
/** 凋零自动清除时间：1 分 30 秒。 */
const WITHER_LIFETIME = 90 * TicksPerSecond
/** 临时凋零的标记，用于兜底清理。 */
const WITHER_TAG = "lucky:temp_wither"

function isAlive(entity) {
    if (!entity) return false
    try {
        const v = entity.isValid
        return typeof v === "function" ? v.call(entity) : v === true
    } catch {
        return false
    }
}

/**
 * @param {import("@minecraft/server").Dimension} dimension
 * @param {{x:number,y:number,z:number}} origin
 * @param {import("@minecraft/server").Player} player 触发者，仅用于提示
 */
export function startWitherStorm(dimension, origin, player) {
    // 雷电：连续 10 秒，每 10 tick 一波
    let elapsed = 0
    const runId = system.runInterval(() => {
        elapsed += STORM_WAVE_INTERVAL
        try {
            const bolts = BOLTS_MIN + Math.floor(Math.random() * (BOLTS_MAX - BOLTS_MIN + 1))
            for (let i = 0; i < bolts; i++) {
                const angle = Math.random() * Math.PI * 2
                const dist = Math.random() * BOLT_RADIUS
                dimension.spawnEntity("minecraft:lightning_bolt", {
                    x: origin.x + Math.cos(angle) * dist,
                    y: origin.y + 1,
                    z: origin.z + Math.sin(angle) * dist,
                })
            }
        } catch {
            // 区块卸载等情况忽略
        }
        if (elapsed >= STORM_TICKS) system.clearRun(runId)
    }, STORM_WAVE_INTERVAL)

    // 凋零
    let wither
    try {
        wither = dimension.spawnEntity("minecraft:wither", { x: origin.x, y: origin.y + 1, z: origin.z })
        wither.addTag(WITHER_TAG)
    } catch {
        wither = undefined
    }

    if (player) {
        try {
            player.onScreenDisplay.setTitle("§4§l厄运降临", {
                subtitle: "§c雷暴与凋零同时出现，快跑！",
                fadeInDuration: 5,
                stayDuration: 40,
                fadeOutDuration: 10,
            })
            player.playSound("ambient.weather.thunder")
        } catch { }
    }

    if (!isAlive(wither)) return

    system.runTimeout(() => {
        try {
            if (isAlive(wither)) wither.remove()
        } catch { }
    }, WITHER_LIFETIME)
}

// 兜底：脚本（重新）加载时清掉上一次会话残留的临时凋零
