{"content": "# -*- coding: utf-8 -*-
"""重绘炸弹球贴图：把之前的绿色色相旋转版换成 TNT 红白花纹。

贴图按 geometry.ice_block 的 box-UV 十字布局逐面绘制：
  - 4 个侧面：TNT 红底 + 中间白色横带 + 白带里挖出红色的 “TNT” 字样（与原版 TNT 侧面同款）
  - 顶/底面：TNT 红底 + 内缩白色方框（箱盖感）
因为模型是“基础盒 + inflate 1 外壳”两层共用同一套 UV，所以整张贴图铺满不透明像素，
不会出现外壳比内层多出来的 1px 圈采到透明像素而破洞。
"""
import json
import os

from PIL import Image

RP = r"C:\Users\UserX\Downloads\幸运方块地图_法杖增强版_竞技场版\resource_packs\LuckyBlock"
GEO = os.path.join(RP, "models", "entity", "ice_block.geo.json")
DST = os.path.join(RP, "textures", "entity", "staffs", "bomb_block.png")

# TNT 配色（红白为主，另两档红做抖动/明暗，避免死板）
RED_A = (163, 51, 30, 255)      # TNT 红底色
RED_B = (146, 42, 23, 255)      # 抖动暗一档
RED_HI = (183, 66, 40, 255)     # 高光红
DARK = (104, 26, 14, 255)       # 描边 / 阴影
WHITE = (232, 231, 226, 255)    # 白带
WHITE_D = (206, 205, 200, 255)  # 白带下沿阴影

# 3×5 点阵字母
GLYPHS = {
    "T": ["###", ".#.", ".#.", ".#.", ".#."],
    "N": ["#.#", "###", "#.#", "#.#", "#.#"],
}


def face_rects(sx, sy, sz, ox, oy):
    """Bedrock box UV 十字布局的 6 个面矩形 (x, y, w, h)。"""
    return {
        "top": (ox + sz, oy, sz, sz),
        "bottom": (ox + sz, oy + sz + sy, sz, sz),
        "left": (ox, oy + sz, sz, sy),
        "front": (ox + sz, oy + sz, sx, sy),
        "right": (ox + sz + sx, oy + sz, sz, sy),
        "back": (ox + sz + sx + sz, oy + sz, sx, sy),
    }


def dither_fill(px, W, H, x, y, w, h, c1, c2, seed=0):
    """两色棋盘抖动铺底，小尺寸下看起来是有颗粒的布/纸质感。"""
    for yy in range(y, y + h):
        for xx in range(x, x + w):
            if 0 <= xx < W and 0 <= yy < H:
                px[xx, yy] = c1 if ((xx + yy + seed) % 2 == 0) else c2


def paint_words(px, x, y, w, h):
    """在白带里用底色挖出 TNT 三个字母（等价于原版 TNT 侧面的字样）。"""
    text = "TNT"
    gw, gh, gap = 3, 5, 1
    total = gw * len(text) + gap * (len(text) - 1)
    if w < total + 2 or h < gh + 2:
        return False
    sx = x + (w - total) // 2
    sy = y + (h - gh) // 2
    for i, ch in enumerate(text):
        g = GLYPHS[ch]
        for r, row in enumerate(g):
            for c, on in enumerate(row):
                if on == "#":
                    px[sx + i * (gw + gap) + c, sy + r] = RED_A
    return True


def paint_side(px, W, H, x, y, w, h, seed):
    dither_fill(px, W, H, x, y, w, h, RED_A, RED_B, seed)
    band_h = max(3, h * 5 // 11)
    band_y = y + (h - band_h) // 2
    for yy in range(band_y, band_y + band_h):
        for xx in range(x, x + w):
            if 0 <= xx < W and 0 <= yy < H:
                px[xx, yy] = WHITE
    # 白带上下各一条暗红细边，让它像“捆带”而不是糊了一片白
    for yy in (band_y - 1, band_y + band_h):
        if y <= yy < y + h:
            for xx in range(x, x + w):
                px[xx, yy] = DARK
    # 白带下沿一档灰，模拟原版的厚度感
    if y <= band_y + band_h - 1 < y + h:
        for xx in range(x, x + w):
            if (xx + band_y) % 3 == 0:
                px[xx, band_y + band_h - 1] = WHITE_D
    paint_words(px, x, band_y, w, band_h)


def paint_cap(px, W, H, x, y, w, h, seed):
    """顶/底面：红底 + 内缩白色方框。"""
    dither_fill(px, W, H, x, y, w, h, RED_A, RED_HI, seed)
    inset, thick = 2, 2
    for i in range(thick):
        yy0, yy1 = y + inset + i, y + h - 1 - inset - i
        xx0, xx1 = x + inset + i, x + w - 1 - inset - i
        if yy0 > yy1 or xx0 > xx1:
            continue
        for xx in range(xx0, xx1 + 1):
            if 0 <= xx < W:
                if 0 <= yy0 < H:
                    px[xx, yy0] = WHITE
                if 0 <= yy1 < H:
                    px[xx, yy1] = WHITE
        for yy in range(yy0, yy1 + 1):
            if 0 <= yy < H:
                if 0 <= xx0 < W:
                    px[xx0, yy] = WHITE
                if 0 <= xx1 < W:
                    px[xx1, yy] = WHITE


with open(GEO, "r", encoding="utf-8") as f:
    geo = json.load(f)
desc = geo["minecraft:geometry"][0]["description"]
W, H = desc["texture_width"], desc["texture_height"]
boxes = geo["minecraft:geometry"][0]["bones"][0]["cubes"]

# 整张铺满 TNT 红，杜绝外壳多出的 1px 圈采到透明像素
img = Image.new("RGBA", (W, H), RED_A)
px = img.load()
for yy in range(H):
    for xx in range(W):
        px[xx, yy] = RED_A if (xx + yy) % 2 == 0 else RED_B

for i, b in enumerate(boxes, 1):
    sx, sy, sz = b["size"]
    ox, oy = b["uv"]
    for name, (x, y, w, h) in face_rects(sx, sy, sz, ox, oy).items():
        if name in ("top", "bottom"):
            paint_cap(px, W, H, x, y, w, h, i)
        else:
            paint_side(px, W, H, x, y, w, h, i)

img.save(DST)
print("已写出", DST, img.size)

# 预览：整张图放大 3 倍 + 只统计可见色彩
PREV = r"C:\Users\UserX\AppData\Local\Temp\lucky\chk\bomb_preview.png"
img.resize((W * 3, H * 3), Image.NEAREST).save(PREV)
print("预览", PREV)
