def body_of(name):
    s = starts[name]
    depth, seen, body = 0, False, []
    for ln in LINES[s:]:
        depth += ln.count("{") - ln.count("}")
        if not seen:
            seen = "{" in ln
            continue
        if depth <= 0:
            break
        body.append(ln)
    return body

def strip(line):
    line = re.sub(r"`[^`]*`", "``", line)
    return re.sub(r'"[^"]*"', '""', line)

